292	    /**
293	     * The owner's {@link #getTelephone() telephone} formatted for humans: the stored E.164
294	     * value rewritten as the country code, a space, then the national digits grouped in threes
295	     * separated by spaces (e.g. {@code '+61 412 345 678'}). The known country codes are
296	     * {@code '+61'} (Australia) and {@code '+1'} (NANP); any other E.164 value is split with a
297	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
298	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
299	     * derived from {@link #getTelephone()}.
300	     */
301	    @Transient
302	    public String getTelephoneDisplay() {
303	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
304	            return null;
305	        }
306	        String digits = this.telephone.substring(1);
307	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
308	        if (digits.length() <= countryCodeLength) {
309	            return this.telephone;
310	        }
311	        String countryCode = digits.substring(0, countryCodeLength);
312	        String national = digits.substring(countryCodeLength);
313	        StringBuilder grouped = new StringBuilder();
314	        for (int i = 0; i < national.length(); i++) {
315	            if (i > 0 && i % 3 == 0) {
316	                grouped.append(' ');
317	            }
318	            grouped.append(national.charAt(i));
319	        }
320	        return "+" + countryCode + " " + grouped;
321	    }
