323	    /**
324	     * The calendar year in which {@code date}'s fiscal year starts. The fiscal year starts on
325	     * 1 July, so a date in July–December belongs to the fiscal year starting that calendar year,
326	     * while a date in January–June belongs to the fiscal year that started the previous calendar
327	     * year.
328	     */
329	    private static int fiscalYearStart(LocalDate date) {
330	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
331	    }
