333	    /**
334	     * The 2-digit fiscal-year segment ({@code 'YY'}) for {@code date}: the last two digits of the
335	     * calendar year in which the fiscal year starts (the fiscal year starts on 1 July), zero-padded
336	     * (e.g. a date in October 2026 yields {@code '26'}). The single authority for the FY segment of
337	     * the owner's {@link #getMemberId() memberId}, reused by the create pipeline so the memberId and
338	     * the derived {@link #getFiscalYear() fiscalYear} agree on it.
339	     */
340	    public static String fiscalYearSegment(LocalDate date) {
341	        return String.format("%02d", fiscalYearStart(date) % 100);
342	    }
