344	    /** The length of the fixed {@code <FY><HASH8><CHK>} tail of a {@link #getMemberId() memberId}
345	     * core: 2 (FY) + 8 (HASH8) + 1 (CHK). The REGION prefix is whatever precedes this tail. */
346	    private static final int MEMBER_ID_TAIL = 11;
347	
348	    /**
349	     * The owner's memberId with any {@code '-<n>'} collision suffix removed, or {@code null} when no
350	     * memberId is set or the value is too short to carry the fixed {@code <FY><HASH8><CHK>} tail.
351	     * The core is {@code <REGION><FY><HASH8><CHK>}; collision handling appends {@code '-<n>'} and
352	     * REGION/FY/HASH8/CHK contain no {@code '-'}, so the segments can be read off the core by length.
353	     */
354	    private String memberIdCore() {
355	        if (this.memberId == null) {
356	            return null;
357	        }
358	        int dash = this.memberId.indexOf('-');
359	        String core = dash < 0 ? this.memberId : this.memberId.substring(0, dash);
360	        return core.length() < MEMBER_ID_TAIL ? null : core;
361	    }
