363	    /**
364	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the 2-digit fiscal-year
365	     * segment of the owner's {@link #getMemberId() memberId} (e.g. a memberId {@code 'NSW261A2B3C4D7'}
366	     * yields {@code 'FY26'}). The memberId's FY segment is derived from the business-day-adjusted
367	     * {@link #getRegistrationDate() registrationDate}. {@code null} when no memberId is set. Not
368	     * persisted — derived from {@link #getMemberId()}.
369	     */
370	    @Transient
371	    public String getFiscalYear() {
372	        String core = memberIdCore();
373	        if (core == null) {
374	            return null;
375	        }
376	        return "FY" + core.substring(core.length() - MEMBER_ID_TAIL, core.length() - MEMBER_ID_TAIL + 2);
377	    }
