454	    /**
455	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
456	     */
457	    private static final Map<String, String> CITY_REGION = Map.of(
458	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
459	
460	    /**
461	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
462	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
463	     */
464	    private static final Map<String, int[]> REGION_RANGE = Map.of(
465	        "NSW", new int[] {2000, 2099},
466	        "VIC", new int[] {3000, 3099},
467	        "QLD", new int[] {4000, 4099});
468	
469	    /**
470	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
471	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
472	     */
473	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
474	        "NSW", "Australia/Sydney",
475	        "VIC", "Australia/Melbourne",
476	        "QLD", "Australia/Brisbane");
477	
478	    /**
479	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
480	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
481	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
482	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
483	     * the owner's {@link #getMemberId() memberId}, so the create pipeline and
484	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
485	     * by the owner pipelines (e.g. postcode validation) rather than copied.
486	     */
487	    public static String regionFor(String postcode, String city) {
488	        String region = regionForPostcode(postcode);
489	        if (region != null) {
490	            return region;
491	        }
492	        String cityRegion = regionForCity(city);
493	        return cityRegion != null ? cityRegion : "UNKNOWN";
494	    }
495	
496	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
497	     * Brisbane->QLD), or {@code null} when the city has no known region. */
498	    public static String regionForCity(String city) {
499	        return city == null ? null : CITY_REGION.get(city);
500	    }
501	
502	    /** Whether {@code region} is one of the known regions (NSW, VIC or QLD); {@code 'UNKNOWN'}
503	     * and any other value are not. Backed by {@link #REGION_RANGE}, the primary source for the
504	     * region set. */
505	    public static boolean isKnownRegion(String region) {
506	        return REGION_RANGE.containsKey(region);
507	    }
508	
509	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
510	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
511	     * range. */
512	    public static String regionForPostcode(String postcode) {
513	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
514	            return null;
515	        }
516	        int value = Integer.parseInt(postcode);
517	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
518	            int[] range = entry.getValue();
519	            if (value >= range[0] && value <= range[1]) {
520	                return entry.getKey();
521	            }
522	        }
523	        return null;
524	    }
