526	    /**
527	     * The owner's locality: the REGION prefix of the owner's {@link #getMemberId() memberId}
528	     * (everything before the fixed {@code <FY><HASH8><CHK>} tail), which the create pipeline derives
529	     * from the postcode-and-city region. {@code 'UNKNOWN'} when no memberId is set. Not persisted —
530	     * derived from {@link #getMemberId()}.
531	     */
532	    @Transient
533	    public String getLocality() {
