679	    public void addPet(Pet pet) {
680	        getPetsInternal().add(pet);
681	        pet.setOwner(this);
682	    }
683	
684	    /**
685	     * Return the Pet with the given name, or null if none found for this Owner.
686	     *
687	     * @param name to test
688	     * @return true if pet name is already in use
689	     */
690	    public Pet getPet(String name) {
691	        return getPet(name, false);
692	    }
693	
694	    /**
695	     * Return the Pet with the given name, or null if none found for this Owner.
696	     *
697	     * @param name to test
698	     * @return true if pet name is already in use
699	     */
700	    public Pet getPet(String name, boolean ignoreNew) {
701	        name = name.toLowerCase();
702	        for (Pet pet : getPetsInternal()) {
703	            if (!ignoreNew || !pet.isNew()) {
704	                String compName = pet.getName();
705	                compName = compName.toLowerCase();
706	                if (compName.equals(name)) {
707	                    return pet;
708	                }
709	            }
710	        }
711	        return null;
712	    }
713	
714	    public Pet getPet(Integer petId) {
715	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
716	    }
717	
718	    @Override
719	    public String toString() {
720	        return new ToStringCreator(this)
721	
722	            .append("id", this.getId())
723	            .append("new", this.isNew())
724	            .append("lastName", this.getLastName())
725	            .append("firstName", this.getFirstName())
726	            .append("address", this.address)
727	            .append("city", this.city)
728	            .append("telephone", this.telephone)
729	            .toString();
730	    }
731	}
